        "Test"
      ],
      "rationale": "The requirement is verified by submitting documents and observing that the system returns exactly one category and a confidence score within the specified range."
    },
    {
      "requirement_id": "AI-002",
      "methods": [
        "Analiz"
      ],
      "rationale": "Achieving a specific macro-averaged F1 score requires statistical analysis of the model's performance on the held-out evaluation set."
    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing behavior for low-confidence documents is verified by submitting documents with confidence scores below 0.60 and observing their placement in the human review queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under load is verified by executing a load test at 50 requests per second and measuring the response time percentiles."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The logging of model version, input hash, and predicted category is verified by inspecting the system logs or database records after processing requests."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting distribution deviation using the population stability index requires statistical analysis of the weekly predicted category distributions against the baseline."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The provision of top three contributing text passages is verified by submitting a document and observing the returned explanation data."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall metrics between Turkish and English documents requires statistical analysis of the model's performance on separate language-specific test sets."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that the specified fields are accepted and stored."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The distinct display of the four triage categories with specific colours is best verified by running the application and visually observing the UI elements."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to record valid vital signs and reject out-of-range values is verified by providing specific input data and observing the system's response."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The offline functionality and local storage capacity are verified by disconnecting the network and creating 500 records to ensure the application remains functional and stores the data."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The synchronization and conflict resolution logic is verified by simulating conflicting edits, restoring connectivity, and observing that both versions are retained for review."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The use of AES-256 encryption is verified by inspecting the code or configuration to confirm the correct cryptographic algorithm and key management are implemented."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The operability with surgical gloves is verified by a user wearing gloves interacting with the tablet interface to demonstrate that all functions are accessible."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Test"
      ],
      "rationale": "The battery life requirement is verified by running the application under the defined usage profile and measuring the duration until the battery is depleted."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresinin doğrulanması için sisteme girdi verilerek harita üzerindeki görsel çıktı ve zamanlama gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük altında performansın ve ekran yenileme hızının doğrulanması için 2.000 izlik senaryonun çalıştırılması ve ölçümlerin yapılması gerekir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Test"
      ],
      "rationale": "Operatörün iz seçimi sonrası doğru bilgilerin ekranda görüntülenip görüntülenmediğinin doğrulanması için etkileşimli test yapılmalıdır."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman tabanlı durum değişikliklerinin (eskime ve kaldırma) doğrulanması için sistemin çalıştırılması ve zaman akışının gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Bölge ihlali durumunda görsel ve sesli uyarıların tetiklenip tetiklenmediğinin doğrulanması için senaryonun çalıştırılması ve çıktının gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj iletim gecikmesinin ve durum bildirimlerinin doğrulanması için mesaj gönderimi yapılarak alıcı tarafındaki sonuç ve zamanlama gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Kayıt işlevinin çalışıp çalışmadığı test ile, kayıtların değiştirilemezlik (immutable) özelliğinin sağlandığı ise log yapısının ve kodun incelenmesi ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Failover senaryosunun doğrulanması için birincil sunucunun arızalandırılması, devralma süresinin ölçülmesi ve veri bütünlüğünün kontrol edilmesi gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek veya simüle edilmiş kimlik doğrulama girdileriyle sistemin çalıştırılarak gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık inaktivite süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışının, zamanlayıcı mekanizmasıyla sistemin çalıştırılarak gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesabın 30 dakika kilitlenmesi davranışının, sisteme girdi verilerek ve sonuç gözlemlenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut ve adet sınırlarının (10 MB, 5 dosya, PDF/JPEG/PNG) sistemin çalıştırılarak farklı girdilerle test edilmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Benzersiz takip numarası üretimi ve e-posta bildirimi işlevinin, başvuru tamamlama işlemi sonrası sistemin çalıştırılarak gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde kaldığı yerden devam etme işlevinin, sistemin çalıştırılarak ve zamanlama senaryolarıyla gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğunun, kullanıcı arayüzü kodunun, yapılandırmasının ve erişilebilirlik özelliklerinin gözle denetlenerek (manuel veya otomatik araçlarla desteklenmiş inceleme) doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanmasının, sistem yapılandırma dosyalarının, altyapı belgelerinin ve sunucu konumlarının gözle denetlenerek doğrulanması gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda sistemin HTTP 429 yanıtı ve Retry-After başlığı üretip üretmediği, kontrollü yük altında test edilerek gözlemlenebilir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "99. yüzdelik dilimdeki gecikme metriklerinin istatistiksel olarak hesaplanması ve 2.000 istek/saniye yük altında performansın modellenmesi analitik bir doğrulama gerektirir."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç servisin yanıt vermemesi senaryosunda ağ geçidinin isteği sonlandırıp HTTP 504 döndürmesi, simüle edilmiş gecikme ile sistemin çalıştırılarak gözlemlenebilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma gerektirmeden ve aktif istekleri düşürmeden uygulanıp uygulanmadığı, canlı sistem üzerinde değişiklik yapılarak gözlemlenebilir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin işlenmesinin ardından günlük dosyasında beklenen alanların (izleme kimliği, süre vb.) doğru şekilde kaydedilip kaydedilmediği, istek gönderimi ve log kontrolü ile test edilebilir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin hesaplanması, uzun vadeli istatistiksel veri toplama ve planlı bakım pencerelerinin hariç tutulması analitik bir değerlendirme gerektirir."
    }
  ]
}

