{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Macro-averaged F1 score validation on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. The held-out evaluation set is available and accessible.",
      "test_inputs": "Held-out evaluation dataset containing labeled documents.",
      "assumptions": "The evaluation script correctly calculates the macro-averaged F1 score.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation set.",
          "expected": "The model generates predictions for all documents in the evaluation set without errors."
        },
        {
          "no": 2,
          "action": "Calculate the macro-averaged F1 score based on the predictions and ground truth labels.",
          "expected": "The calculated macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. The held-out evaluation set contains a sufficient number of documents labeled as Turkish and English.",
      "test_inputs": "Held-out evaluation dataset containing labeled documents in Turkish and English.",
      "assumptions": "The evaluation script correctly calculates recall per language group.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation set.",
          "expected": "The model generates predictions for all documents in the evaluation set without errors."
        },
        {
          "no": 2,
          "action": "Calculate the recall score for documents written in Turkish.",
          "expected": "A recall value for Turkish documents is obtained."
        },
        {
          "no": 3,
          "action": "Calculate the recall score for documents written in English.",
          "expected": "A recall value for English documents is obtained."
        },
        {
          "no": 4,
          "action": "Calculate the absolute difference between the Turkish and English recall scores in percentage points.",
          "expected": "The absolute difference is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
