  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed on the tablet and a test casualty record has been created and saved.",
      "test_inputs": "A sample casualty record with unique identifiable data (e.g., Patient ID: TEST-123, Name: John Doe).",
      "assumptions": "The device file system allows direct inspection of storage files by the test engineer.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record in the application with the test input data and save it.",
          "expected": "The application confirms the record has been saved successfully."
        },
        {
          "no": 2,
          "action": "Access the underlying storage file or database file on the device where the casualty data is persisted.",
          "expected": "The file is accessible but the content is not human-readable plain text."
        },
        {
          "no": 3,
          "action": "Analyze the storage file using a hex editor or forensic tool to inspect the data structure.",
          "expected": "The data appears encrypted; the specific test input strings (e.g., 'TEST-123', 'John Doe') are not visible in the raw file content."
        },
        {
          "no": 4,
          "action": "Verify the encryption algorithm configuration or metadata associated with the stored data if exposed via system logs or configuration files.",
          "expected": "The configuration or metadata indicates that AES-256 is the active encryption standard for the data store."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Battery life under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100% battery) and the application is installed. The 'defined usage profile' is documented and available for the test engineer to follow.",
      "test_inputs": "The defined usage profile script (e.g., continuous data entry, screen on, specific brightness, network activity).",
      "assumptions": "The 'defined usage profile' is a specific, repeatable sequence of operations documented in the project requirements or test plan. If not explicitly provided, a standard triage workflow (screen on, periodic data entry, GPS active) is assumed as the profile.",
      "steps": [
        {
          "no": 1,
          "action": "Start the tablet with 100% battery and launch the application.",
          "expected": "The application starts and the battery indicator shows 100%."
        },
        {
          "no": 2,
          "action": "Execute the defined usage profile continuously without interruption (e.g., performing triage entries, viewing records, maintaining screen on).",
          "expected": "The application remains responsive and functional throughout the usage profile execution."
        },
        {
          "no": 3,
          "action": "Monitor the battery level and elapsed time until the battery reaches a critical low level or the device shuts down.",
          "expected": "The device continues to operate for at least 8 hours before the battery is depleted or the device powers off."
        }
      ]
    }
  ]
}

