{
  "test_cases": [
    {
      "id": "TC-SW-003-01",
      "title": "İstemci başına dakikada 600 istek sınırının uygulanması",
      "covers": [
        "SW-003"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "Ağ geçidi çalışmaktadır ve test istemcisi için hız sınırı yapılandırması 600 istek/dakika olarak ayarlanmıştır.",
      "test_inputs": "Tek bir istemci kimliği ile 600 adet geçerli HTTP isteği.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Tek bir istemci kimliği kullanarak 600 adet HTTP isteği gönderilir.",
          "expected": "Tüm 600 istek için HTTP 200 (veya ilgili başarılı durum kodu) yanıtı alınır."
